//! Independent induction fixtures generated by `generate.py`.
//!
//! The CSV files are committed; tests parse them with this small std-only
//! reader. `mpmath` is a generation-time dependency only.

/// One independently generated unit-current vector-potential row.
#[derive(Debug, Clone, PartialEq)]
pub struct Row {
    pub r: f64,
    pub z: f64,
    pub softening: f64,
    pub reference: f64,
}

/// Rows for the `loop` or `solenoid` fixture case.
pub fn rows(case: &str) -> Vec<Row> {
    let text = match case {
        "loop" => include_str!("loop.csv"),
        "solenoid" => include_str!("solenoid.csv"),
        other => panic!("unknown induction fixture case {other:?}"),
    };
    parse(text)
}

fn parse(text: &str) -> Vec<Row> {
    let mut rows = Vec::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') || line.starts_with("case,") {
            continue;
        }
        let fields: Vec<&str> = line.split(',').map(str::trim).collect();
        assert_eq!(fields.len(), 5, "bad induction fixture row {line:?}");
        rows.push(Row {
            r: fields[1].parse().expect("fixture r"),
            z: fields[2].parse().expect("fixture z"),
            softening: fields[3].parse().expect("fixture softening"),
            reference: fields[4].parse().expect("fixture reference"),
        });
    }
    rows
}
